<?php
namespace App\Services; use App\Core\Database;use App\Core\Auth;
final class UserService{public function create(array $d):int{$s=Database::pdo()->prepare('INSERT INTO users(tenant_id,full_name,email,username,password,role_id,designation,phone,is_active,is_banned,created_at,updated_at) VALUES(1,?,?,?,?,?,?,?,1,0,NOW(),NOW())');$s->execute([$d['full_name'],$d['email']??null,$d['username'],password_hash($d['password'],PASSWORD_DEFAULT),$d['role_id']?:null,$d['designation']??null,$d['phone']??null]);$id=(int)Database::pdo()->lastInsertId();(new ActivityService)->record('USER_CREATED','System','user',$id,null,'stage_3');return $id;}public function update(int $id,array $d):void{$repo=new \App\Repositories\UserRepository;$before=$repo->find($id);if(!$before)throw new \RuntimeException('User not found');$fields=['full_name=?','email=?','username=?','role_id=?','designation=?','phone=?','is_active=?','is_banned=?'];$params=[$d['full_name'],$d['email']??null,$d['username'],$d['role_id']?:null,$d['designation']??null,$d['phone']??null,!empty($d['is_active'])?1:0,!empty($d['is_banned'])?1:0];if(!empty($d['password'])){$fields[]='password=?';$params[]=password_hash($d['password'],PASSWORD_DEFAULT);}$params[]=$id;Database::pdo()->prepare('UPDATE users SET '.implode(',',$fields).',updated_at=NOW() WHERE id=?')->execute($params);$after=$repo->find($id);(new ActivityService)->record('USER_UPDATED','System','user',$id,(new ActivityService)->diff($before,$after,['password']),'stage_3');}}
